def extract_demo(txt,n):
 m=re.search(rf'Demo pair {n} input \(28x28\):\n(.*?)\nDemo pair {n} output \(28x28\):\n(.*?)(?=\n\nSame instance)',txt,re.S)
 if not m: print('no match'); return
 parse=lambda s:[[int(x) for x in line.split()] for line in s.strip().splitlines()]
 return parse(m.group(1)),parse(m.group(2))
